(4037974, 577067, 15711, '<td valign="top">Love the fish eye. Great composition. I wish you could have dodged the guy a touch, but ... well, basic editing stinks.<br/> <br/>Great sky. 7</td>', 'Love the fish eye. Great composition. I wish you could have dodged the guy a touch, but ... well, basic editing stinks. Great sky. 7', '2007-08-29 10:27:47.000000', NULL, 1),
(4037978, 576183, 15711, '<td valign="top">AWWWWW.  That is great, with the up in the air sense and the ears back.  Nice.  If I could change a thing, I might tweak the contrast a smidge and maybe crop to eliminate that puddle of water in the upper left. Still, I like it. 7</td>', 'AWWWWW.  That is great, with the up in the air sense and the ears back.  Nice.  If I could change a thing, I might tweak the contrast a smidge and maybe crop to eliminate that puddle of water in the upper left. Still, I like it. 7', '2007-08-29 10:28:59.000000', NULL, 1),
(4037982, 578464, 15711, '<td valign="top">This is fun. I like the over saturated colors. A bit of a snapshot feel but the colors help that aspect of it.</td>', 'This is fun. I like the over saturated colors. A bit of a snapshot feel but the colors help that aspect of it.', '2007-08-29 10:30:28.000000', NULL, 1),
