(4039572, 578350, 32334, '<td valign="top">Not a bad image, but I think I would have liked either more focus in the speedometer, or the camera pulled back farther to give more view of the side windows and the inside of the car.</td>', 'Not a bad image, but I think I would have liked either more focus in the speedometer, or the camera pulled back farther to give more view of the side windows and the inside of the car.', '2007-08-29 19:15:07.000000', NULL, 1),
(4039575, 578659, 32334, '<td valign="top">Good image.  I really like how the cloud bank on the upper right kinda rhymes off the wave on the left.</td>', 'Good image.  I really like how the cloud bank on the upper right kinda rhymes off the wave on the left.', '2007-08-29 19:15:45.000000', NULL, 1),
(4039577, 578128, 32334, '<td valign="top">Good capture, but I wish the kids head was crisper, rather than the front of the trike.</td>', 'Good capture, but I wish the kids head was crisper, rather than the front of the trike.', '2007-08-29 19:16:38.000000', NULL, 1),
