(4041314, 578476, 68586, '<td valign="top">This certainly shows speed, and having looked ''Lapidary'' up in the dictionary I now know another word  :  )<br/> <br/>My only real issue is that even with the title explained I still can''t really see what is (or isn''t ) going on.<br/> <br/>I like the idea, and the crop, but it probably lacks the wow factor that people will be looking for in either having a splash of colour or really crisp focus.<br/> <br/>Good luck though.</td>', 'This certainly shows speed, and having looked ''Lapidary'' up in the dictionary I now know another word  :  ) My only real issue is that even with the title explained I still can''t really see what is (or isn''t ) going on. I like the idea, and the crop, but it probably lacks the wow factor that people will be looking for in either having a splash of colour or really crisp focus. Good luck though.', '2007-08-30 10:54:22.000000', NULL, 1),
(4041318, 577430, 42100, '<td valign="top">Nice crisp, clean and cheery color. The artistic tilt really works well for this photo.  Very nice!</td>', 'Nice crisp, clean and cheery color. The artistic tilt really works well for this photo.  Very nice!', '2007-08-30 11:00:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4041319, 577958, 68586, '<td valign="top">I do love go-karts  :  )<br/> <br/>Always a good place for speed and a splash of colour. I think to lift this points wise it would have been good if you could have captured the kart coming out of a corner, or even approaching you, rather than just having passed. That way you get a little more dynamic tension and involve the viewer more. Good crisp shot though.</td>', 'I do love go-karts  :  ) Always a good place for speed and a splash of colour. I think to lift this points wise it would have been good if you could have captured the kart coming out of a corner, or even approaching you, rather than just having passed. That way you get a little more dynamic tension and involve the viewer more. Good crisp shot though.', '2007-08-30 11:01:12.000000', NULL, 1),
(4041320, 578674, 42100, '<td valign="top">Very nice crisp, clean detail and color.  Good composition as well.  Nicely done!</td>', 'Very nice crisp, clean detail and color.  Good composition as well.  Nicely done!', '2007-08-30 11:01:12.000000', NULL, 1),
(4041323, 577902, 68586, '<td valign="top">Steam engines are quite magnificent, and always photogenic.<br/> <br/>My only slight issue with this shot is that it doesn''t (to me) convey any idea of speed - fast or slow. It might be that the train was actually moving and you have captured it with a reasonably fast shutter speed . .  but it could also be a static exhibit.<br/> <br/>Nice train though.</td>', 'Steam engines are quite magnificent, and always photogenic. My only slight issue with this shot is that it doesn''t (to me) convey any idea of speed - fast or slow. It might be that the train was actually moving and you have captured it with a reasonably fast shutter speed . .  but it could also be a static exhibit. Nice train though.', '2007-08-30 11:05:02.000000', NULL, 1),
(4041327, 577522, 42100, '<td valign="top">Summer time fun!  Kids really love that kind of play and you really captured a great moment well.</td>', 'Summer time fun!  Kids really love that kind of play and you really captured a great moment well.', '2007-08-30 11:06:51.000000', NULL, 1),
(4041345, 577958, 42100, '<td valign="top">Totally looks like a blast.  Very nice color and clarity.  The motion blur really make the cart and driver pop.  Very nice!</td>', 'Totally looks like a blast.  Very nice color and clarity.  The motion blur really make the cart and driver pop.  Very nice!', '2007-08-30 11:10:47.000000', NULL, 1),
(4041349, 577990, 68586, '<td valign="top">Yikes - that gets the plowing done quickly   :  )<br/> <br/>It''s a great idea for a speed challenge, with nice bright colours, but I think it might suffer points wise from being a little small and grainy. <br/> <br/>Clearly fits the challenge though.</td>', 'Yikes - that gets the plowing done quickly   :  ) It''s a great idea for a speed challenge, with nice bright colours, but I think it might suffer points wise from being a little small and grainy.  Clearly fits the challenge though.', '2007-08-30 11:11:54.000000', NULL, 1),
(4041355, 577619, 68586, '<td valign="top">The first slow ''speed'' picture I''ve come across so far in this challenge. Blurred water can always look nice - I wonder whether it might have had more impact if you had cropped right in to where the water is moving around the rocks ?<br/> <br/>Great looking river though !</td>', 'The first slow ''speed'' picture I''ve come across so far in this challenge. Blurred water can always look nice - I wonder whether it might have had more impact if you had cropped right in to where the water is moving around the rocks ? Great looking river though !', '2007-08-30 11:14:14.000000', NULL, 1),
(4041373, 577711, 68586, '<td valign="top">Slugs and snails can make wonderful shots as demonstrated by the likes of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=69368" rel="nofollow" target="_blank">bubeltrubel</a> but to get the best effect really takes some careful lighting and sharp focus.<br/> <br/>No problem with this showing speed (or lack of) you just need to adjust the focus slightly and your angle.</td>', 'Slugs and snails can make wonderful shots as demonstrated by the likes of  bubeltrubel but to get the best effect really takes some careful lighting and sharp focus. No problem with this showing speed (or lack of) you just need to adjust the focus slightly and your angle.', '2007-08-30 11:20:28.000000', NULL, 1),
(4041377, 578275, 78303, '<td valign="top">Bonus points for getting it in right at the deadline!</td>', 'Bonus points for getting it in right at the deadline!', '2007-08-30 11:21:16.000000', NULL, 1),
