(4047741, 575966, 81691, '<td valign="top">These shots are really difficult to get down, from what I''ve heard.  For the best shots of this type that I have seen, the photographer used at least three light sources and some white boards/reflectors for background and lighting.</td>', 'These shots are really difficult to get down, from what I''ve heard.  For the best shots of this type that I have seen, the photographer used at least three light sources and some white boards/reflectors for background and lighting.', '2007-09-01 17:54:25.000000', NULL, 1),
(4047743, 575696, 81691, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2007-09-01 17:54:51.000000', NULL, 1),
(4047754, 578111, 81691, '<td valign="top">Great color, composition, DOF, and lighting!  Best I''ve seen yet for this challenge.</td>', 'Great color, composition, DOF, and lighting!  Best I''ve seen yet for this challenge.', '2007-09-01 17:59:36.000000', NULL, 1),
(4047758, 577629, 81691, '<td valign="top">Best I''ve seen so far of the many horse race shots in this challenge.</td>', 'Best I''ve seen so far of the many horse race shots in this challenge.', '2007-09-01 18:01:08.000000', NULL, 1),
(4047772, 577328, 81691, '<td valign="top">Good shot!  Better lighting and a crisper image would have made this shot awesome.</td>', 'Good shot!  Better lighting and a crisper image would have made this shot awesome.', '2007-09-01 18:06:01.000000', NULL, 1),
(4047774, 578503, 81691, '<td valign="top">I like the fire extinguisher on the edge of the shot.</td>', 'I like the fire extinguisher on the edge of the shot.', '2007-09-01 18:06:53.000000', NULL, 1),
