(4047864, 577023, 83312, '<td valign="top">this isnt speedy at all</td>', 'this isnt speedy at all', '2007-09-01 18:51:47.000000', NULL, 1),
(4048128, 578395, 14437, '<td valign="top">I would have preferred all snails to be in focus.</td>', 'I would have preferred all snails to be in focus.', '2007-09-01 21:22:45.000000', NULL, 1),
(4048273, 578515, 42254, '<td valign="top">Lovely--looks like slow motion, but in reality it''s not so!</td>', 'Lovely--looks like slow motion, but in reality it''s not so!', '2007-09-01 22:09:08.000000', NULL, 1),
(4048304, 578096, 42254, '<td valign="top">Great shot! You caught the wheel motion while keeping the frame sharp.  Looks like it may have been a wet street to provide the reflection.</td>', 'Great shot! You caught the wheel motion while keeping the frame sharp.  Looks like it may have been a wet street to provide the reflection.', '2007-09-01 22:22:58.000000', NULL, 1),
(4048360, 577867, 19786, '<td valign="top">Love the angle and the reflections</td>', 'Love the angle and the reflections', '2007-09-01 22:55:36.000000', NULL, 1),
(4048365, 578610, 19786, '<td valign="top">This brings back memories of my 72 monte carlo, nice</td>', 'This brings back memories of my 72 monte carlo, nice', '2007-09-01 22:56:50.000000', NULL, 1),
(4048366, 576833, 19786, '<td valign="top">Great timing. Outstanding shot.</td>', 'Great timing. Outstanding shot.', '2007-09-01 22:57:37.000000', NULL, 1),
(4048368, 578256, 19786, '<td valign="top">Sharp focus and great color.</td>', 'Sharp focus and great color.', '2007-09-01 22:58:21.000000', NULL, 1),
(4048394, 578143, 19786, '<td valign="top">Interesting Lighting.</td>', 'Interesting Lighting.', '2007-09-01 23:08:01.000000', NULL, 1),
(4048401, 577328, 19786, '<td valign="top">Great focus, both on the part of the camera and the dog.</td>', 'Great focus, both on the part of the camera and the dog.', '2007-09-01 23:10:37.000000', NULL, 1),
(4048404, 577508, 19786, '<td valign="top">Its a nice shot but no idea of speed, it looks parked.</td>', 'Its a nice shot but no idea of speed, it looks parked.', '2007-09-01 23:11:26.000000', NULL, 1),
(4048416, 578098, 19786, '<td valign="top">Interesting angel.  I like the image in the rear view.</td>', 'Interesting angel.  I like the image in the rear view.', '2007-09-01 23:14:19.000000', NULL, 1),
(4048427, 578167, 19786, '<td valign="top">I wonder if you too were flying in order to get this shot?</td>', 'I wonder if you too were flying in order to get this shot?', '2007-09-01 23:16:40.000000', NULL, 1),
(4048452, 578670, 19786, '<td valign="top">I''d be very interested to know how you got this shot.  Beautiful!!!</td>', 'I''d be very interested to know how you got this shot.  Beautiful!!!', '2007-09-01 23:22:43.000000', NULL, 1),
(4048754, 578096, 76430, '<td valign="top">One of the best I''ve seen so far.  Good reflection and sense of speed.</td>', 'One of the best I''ve seen so far.  Good reflection and sense of speed.', '2007-09-02 00:58:43.000000', NULL, 1),
(4048767, 576741, 60862, '<td valign="top">I *have* to go on that! :) Nice composition, and having some of them sharper than the back adds to the feeling of whoosh!" :)</td>', 'I *have* to go on that! :) Nice composition, and having some of them sharper than the back adds to the feeling of whoosh!" :)', '2007-09-02 01:07:12.000000', NULL, 1),
(4048769, 578283, 60862, '<td valign="top">A little too orange.</td>', 'A little too orange.', '2007-09-02 01:07:38.000000', NULL, 1),
(4048774, 577342, 60862, '<td valign="top">The composition leaves me wondering what I''m supposed to look at, and the numerous distracting elements (lamps, signs ...) further confuse the issue.</td>', 'The composition leaves me wondering what I''m supposed to look at, and the numerous distracting elements (lamps, signs ...) further confuse the issue.', '2007-09-02 01:08:58.000000', NULL, 1),
(4048777, 578167, 60862, '<td valign="top">Were they really diving?  Either way, the angle really adds to the feeling of speed.</td>', 'Were they really diving?  Either way, the angle really adds to the feeling of speed.', '2007-09-02 01:09:32.000000', NULL, 1),
(4048780, 578672, 60862, '<td valign="top">This confuses me.  Why would you hit your CPU with a hammer?</td>', 'This confuses me.  Why would you hit your CPU with a hammer?', '2007-09-02 01:10:23.000000', NULL, 1),
(4048781, 577399, 60862, '<td valign="top">Ha!</td>', 'Ha!', '2007-09-02 01:10:40.000000', NULL, 1),
(4048787, 578515, 60862, '<td valign="top">Hey ... did you see my Sacred entry? I''d love to know I inspired someone. :)<br/> <br/>This is pretty!  The sky''s a bit too bright, though - it detracts from the swirling stars.  Also, the very bright slash on the right side breaks up the nice silhouette of the horizon.</td>', 'Hey ... did you see my Sacred entry? I''d love to know I inspired someone. :) This is pretty!  The sky''s a bit too bright, though - it detracts from the swirling stars.  Also, the very bright slash on the right side breaks up the nice silhouette of the horizon.', '2007-09-02 01:13:42.000000', NULL, 1),
(4048791, 577298, 60862, '<td valign="top">Oooh - fast commuters!  I like this very much.  That staring painting dares me to look away.</td>', 'Oooh - fast commuters!  I like this very much.  That staring painting dares me to look away.', '2007-09-02 01:14:50.000000', NULL, 1),
(4048793, 578445, 60862, '<td valign="top">A little to small in the frame.  I''m trying to imagine it with about the outer 3/4 cropped out. I like the diagonal line of the mountain, and the pure silhouette is fine with me.</td>', 'A little to small in the frame.  I''m trying to imagine it with about the outer 3/4 cropped out. I like the diagonal line of the mountain, and the pure silhouette is fine with me.', '2007-09-02 01:15:42.000000', NULL, 1),
(4048796, 578395, 81082, '<td valign="top">I like the picture, but I would have liked it better if the No. 4 snail wasn''t blurry. Nice work, though!</td>', 'I like the picture, but I would have liked it better if the No. 4 snail wasn''t blurry. Nice work, though!', '2007-09-02 01:16:00.000000', NULL, 1),
(4048802, 576884, 60862, '<td valign="top">Heh - another spinning star shot.  I keep wondering whether someone saw my recent Sacred entry ...<br/> <br/>This is pretty - I like the purple color.  I''d just like there to be a little more foreground for context.  It''s the contrast between the swirling stars and the dead-still ground that creates the most visual interest for me.</td>', 'Heh - another spinning star shot.  I keep wondering whether someone saw my recent Sacred entry ... This is pretty - I like the purple color.  I''d just like there to be a little more foreground for context.  It''s the contrast between the swirling stars and the dead-still ground that creates the most visual interest for me.', '2007-09-02 01:17:15.000000', NULL, 1),
(4048807, 576929, 60862, '<td valign="top">It''s an impressive bird, but isn''t he sitting still, not at killing speed?</td>', 'It''s an impressive bird, but isn''t he sitting still, not at killing speed?', '2007-09-02 01:18:00.000000', NULL, 1),
