(4057495, 577329, 68586, '<td valign="top">Great leap from the leading dog.</td>', 'Great leap from the leading dog.', '2007-09-04 17:16:12.000000', NULL, 1),
(4057496, 578471, 68586, '<td valign="top">Always a nice subject for speed/motion blur.<br/> <br/>Love the purples on the uprights. I wonder whether it would have worked to have a the wheel in a bit more context though rather than just isolated ?</td>', 'Always a nice subject for speed/motion blur. Love the purples on the uprights. I wonder whether it would have worked to have a the wheel in a bit more context though rather than just isolated ?', '2007-09-04 17:16:16.000000', NULL, 1),
