(4061405, 577067, 42567, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Judi:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by philup:</b></div><hr/><i> Too Cool Judi!!!  Nice job as always!  Congratulations on your ribbon </i></td></tr></table> <br/> <br/>Ribbon?? </i></td></tr></table> <br/> <br/>Ok, sorry about that...Honorable Mention.  Is that better? :)<br/> <br/></td>', 'Originally posted by Judi: Originally posted by philup: Too Cool Judi!!!  Nice job as always!  Congratulations on your ribbon   Ribbon??   Ok, sorry about that...Honorable Mention.  Is that better? :) ', '2007-09-05 12:47:18.000000', NULL, 0),
